from __future__ import annotations

import difflib
import sys
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional

EXIT_USAGE = 2


class UsageError(Exception):
    """Raised for any command-line usage problem; always exits with code 2."""


@dataclass
class Option:
    """A declaratively-typed option.

    kind: "int" | "str" | "flag" (bool) | "append" (repeatable str)
    """

    name: str  # long form, e.g. "--times"
    kind: str = "str"
    help: str = ""
    required: bool = False
    default: Any = None

    # derived defaults per kind
    def __post_init__(self) -> None:
        if not self.name.startswith("--"):
            raise ValueError(f"option {self.name!r} must use long form '--name'")
        if self.kind not in ("int", "str", "flag", "append"):
            raise ValueError(f"unknown option kind {self.kind!r}")
        self._value: Any = None

    @property
    def key(self) -> str:
        return self.name.lstrip("-").replace("-", "_")

    @property
    def metavar(self) -> str:
        return self.key.upper()

    def initial(self) -> Any:
        if self.kind == "flag":
            return self.default if self.default is not None else False
        if self.kind == "append":
            return list(self.default) if self.default else []
        return self.default

    def coerce(self, raw: str) -> Any:
        if self.kind == "int":
            try:
                return int(raw)
            except ValueError:
                raise UsageError(
                    f"invalid value for {self.name}: {raw!r} is not a valid int"
                ) from None
        return raw

    def consume(self, argv: List[str], i: int, values: Dict[str, Any]) -> int:
        """Consume this option from argv at position i; return next position."""
        token = argv[i]
        if token == "--help" or token == "-h":
            raise _HelpRequested()
        if token != self.name and not token.startswith(self.name + "="):
            return i + 1 if False else -1  # not ours; caller handles scan
        if self.kind == "flag":
            values[self.key] = True
            return i + 1
        if "=" in token:
            raw = token.split("=", 1)[1]
            nxt = i + 1
        else:
            if i + 1 >= len(argv):
                raise UsageError(f"{self.name}: expected one argument")
            raw = argv[i + 1]
            nxt = i + 2
        coerced = self.coerce(raw)
        if self.kind == "append":
            values[self.key].append(coerced)
        else:
            values[self.key] = coerced
        self._seen.add(self.name)
        return nxt


# Small internal sentinel used to unwind to the help printer.
class _HelpRequested(Exception):
    pass


Option.consume.__doc__ = Option.consume.__doc__  # keep docstring intact


@dataclass
class Command:
    name: str
    description: str
    options: List[Option] = field(default_factory=list)

    def sorted_options(self) -> List[Option]:
        return sorted(self.options, key=lambda o: o.name)

    def usage_line(self, prog: str) -> str:
        parts = [f"usage: {prog} {self.name}"]
        parts.append("[-h]")
        for opt in self.sorted_options():
            if opt.kind == "flag":
                parts.append(f"[{opt.name}]")
            elif opt.required:
                parts.append(f"{opt.name} {opt.metavar}")
            else:
                parts.append(f"[{opt.name} {opt.metavar}]")
        return " ".join(parts)

    def help_text(self, prog: str) -> str:
        lines = [self.usage_line(prog), "", self.description.strip(), "", "options:"]
        entries = [("  -h, --help", "show this help message and exit")]
        for opt in self.sorted_options():
            left = f"  {opt.name}"
            if opt.kind != "flag":
                left += f" {opt.metavar}"
            tag = ""
            if opt.required:
                tag = "(required)"
            elif opt.default is not None and opt.kind not in ("append",):
                tag = f"(default: {opt.default!r})"
            elif opt.kind == "append":
                tag = "(repeatable)"
            help_bits = [opt.help] if opt.help else []
            if tag:
                help_bits.append(tag)
            text = " ".join(help_bits)
            entries.append((left, text))
        width = max(len(left) for left, _ in entries) + 2
        out = list(lines)
        for left, text in entries:
            if text:
                out.append(f"{left:<{width}}{text}")
            else:
                out.append(left.rstrip())
        return "\n".join(out)


class Argonaut:
    """Registry of subcommands; parses argv into a dict."""

    def __init__(self, prog: Optional[str] = None, description: str = "") -> None:
        self.prog = prog or "prog"
        self.description = description
        self.commands: Dict[str, Command] = {}

    def add_command(
        self, name: str, description: str = "", options: Optional[List[Option]] = None
    ) -> Command:
        cmd = Command(name=name, description=description, options=list(options or []))
        self.commands[name] = cmd
        return cmd

    # -- error helpers ---------------------------------------------------

    def _fail(self, message: str) -> None:
        print(f"{self.prog}: error: {message}", file=sys.stderr)
        raise SystemExit(EXIT_USAGE)

    # -- parsing ---------------------------------------------------------

    def parse_args(self, argv: Optional[List[str]] = None) -> Dict[str, Any]:
        argv = list(sys.argv[1:] if argv is None else argv)

        if not argv or argv[0] in ("-h", "--help"):
            print(self._root_help())
            raise SystemExit(0)

        name = argv[0]
        if name not in self.commands:
            close = difflib.get_close_matches(name, self.commands.keys(), n=3)
            msg = f"unknown subcommand {name!r}"
            if close:
                msg += "; did you mean " + ", ".join(repr(c) for c in close) + "?"
            self._fail(msg)

        cmd = self.commands[name]
        rest = argv[1:]

        if "-h" in rest or "--help" in rest:
            print(cmd.help_text(self.prog))
            raise SystemExit(0)

        values: Dict[str, Any] = {}
        seen = set()
        for opt in cmd.options:
            values[opt.key] = opt.initial()

        i = 0
        while i < len(rest):
            token = rest[i]
            match = next(
                (o for o in cmd.options if token.startswith(o.name)), None
            )
            if match is None:
                self._fail(f"unrecognized argument for {cmd.name!r}: {token}")
            # inline '=' form
            if "=" in token and match.kind != "flag":
                _, _, raw = token.partition("=")
                if raw == "":
                    self._fail(f"{match.name}: expected one argument")
                coerced = match.coerce(raw)
                if match.kind == "append":
                    values[match.key].append(coerced)
                else:
                    values[match.key] = coerced
                seen.add(match.key)
                i += 1
                continue
            if match.kind == "flag":
                values[match.key] = True
                seen.add(match.key)
                i += 1
                continue
            if i + 1 >= len(rest):
                self._fail(f"{match.name}: expected one argument")
            values[match.key] = match.coerce(rest[i + 1])
            seen.add(match.key)
            i += 2

        missing = [
            o for o in cmd.options if o.required and values[o.key] is None
        ]
        if missing:
            names = ", ".join(o.name for o in missing)
            self._fail(f"missing required option(s): {names}")

        result = {"command": cmd.name}
        result.update(values)
        return result

    # -- help ------------------------------------------------------------

    def _root_help(self) -> str:
        lines = [f"usage: {self.prog} [-h] {{{','.join(sorted(self.commands))}}}", ""]
        if self.description:
            lines += [self.description.strip(), ""]
        lines.append("subcommands:")
        width = max((len(n) for n in self.commands), default=0) + 2
        for name in sorted(self.commands):
            desc = self.commands[name].description
            lines.append(f"  {name:<{width}}{desc}")
        lines.append("")
        lines.append("run 'prog <subcommand> --help' for details on a subcommand.")
        return "\n".join(lines)
"})
